insert into public.quiz_questions
  (type_contenu, slug, ordre, question_fr, question_en, choix_fr, choix_en, bonne_reponse, explication_fr, explication_en)
values
  ('heros', 'reine-nzinga', 1, $q$Selon la tradition, d'où vient le prénom Njinga ?$q$, $q$According to tradition, where does the name Njinga come from?$q$, $q$["D'un mot qui signifie « reine guerrière »", "D'un mot qui évoque l'action de tordre, d'enrouler", "Du nom du fleuve Kwanza", "Du nom de sa grand-mère paternelle"]$q$::jsonb, $q$["From a word meaning 'warrior queen'", "From a word evoking the act of twisting, of winding", "From the name of the Kwanza River", "From the name of her paternal grandmother"]$q$::jsonb, 1, $q$On raconte que le cordon ombilical était enroulé autour de son cou à la naissance. Son nom vient d'un mot kimbundu qui évoque l'action de tordre.$q$, $q$It is said the umbilical cord was wound around her neck at birth. Her name comes from a Kimbundu word evoking the act of twisting.$q$),
  ('heros', 'reine-nzinga', 2, $q$Contre quelle puissance coloniale Njinga s'est-elle battue toute sa vie ?$q$, $q$Which colonial power did Njinga fight against all her life?$q$, $q$["L'Espagne", "La France", "Le Portugal", "L'Angleterre"]$q$::jsonb, $q$["Spain", "France", "Portugal", "England"]$q$::jsonb, 2, $q$Njinga a résisté au Portugal, installé à Luanda, pendant plus de quarante ans, sans jamais perdre sa couronne.$q$, $q$Njinga resisted Portugal, based in Luanda, for more than forty years, without ever losing her crown.$q$),
  ('heros', 'reine-nzinga', 3, $q$D'après la tradition, comment Njinga s'est-elle assise face au gouverneur portugais à Luanda ?$q$, $q$According to tradition, how did Njinga sit facing the Portuguese governor in Luanda?$q$, $q$["Sur le dos d'une servante", "Debout sur une table", "Sur un trône venu de Ndongo", "Sur le siège du gouverneur"]$q$::jsonb, $q$["On the back of a servant", "Standing on a table", "On a throne brought from Ndongo", "In the governor's own chair"]$q$::jsonb, 0, $q$Selon la tradition, faute de siège, elle s'assit sur le dos d'une servante pour négocier d'égale à égal. Aucun témoin direct ne l'a rapporté.$q$, $q$According to tradition, with no chair for her, she sat on a servant's back to negotiate as an equal. No direct witness recorded it.$q$),
  ('heros', 'reine-nzinga', 4, $q$Chassée de son royaume, à quel peuple guerrier Njinga s'allie-t-elle pour revenir ?$q$, $q$Driven from her kingdom, which warrior people did Njinga ally with to return?$q$, $q$["Les Mbundu", "Les Kongo", "Les Ovimbundu", "Les Imbangala"]$q$::jsonb, $q$["The Mbundu", "The Kongo", "The Ovimbundu", "The Imbangala"]$q$::jsonb, 3, $q$Elle s'allie aux Imbangala, guerriers nomades redoutés, épouse leur chef Kasanje et conquiert avec eux le royaume de Matamba.$q$, $q$She allied with the Imbangala, feared nomadic warriors, married their chief Kasanje and conquered the kingdom of Matamba with them.$q$),
  ('heros', 'reine-nzinga', 5, $q$Que conserve Njinga grâce au traité de paix signé avec le Portugal en 1656 ?$q$, $q$What did Njinga keep thanks to the 1656 peace treaty with Portugal?$q$, $q$["Le port de Luanda", "Les terres côtières de Ndongo", "Sa souveraineté sur Matamba", "Son alliance avec les Hollandais"]$q$::jsonb, $q$["The port of Luanda", "The coastal lands of Ndongo", "Her sovereignty over Matamba", "Her alliance with the Dutch"]$q$::jsonb, 2, $q$Elle cède des terres côtières mais garde sa souveraineté sur Matamba : le royaume n'est pas colonisé. C'est la victoire d'une vie de résistance.$q$, $q$She cedes coastal lands but keeps her sovereignty over Matamba: the kingdom is not colonised. It is the victory of a lifetime of resistance.$q$),
  ('heros', 'martin-paul-samba', 1, $q$Quel était le nom de naissance de Martin Paul Samba ?$q$, $q$What was Martin Paul Samba's birth name?$q$, $q$["Ngosso Din", "Edande Mbita", "Madola", "Mebenga m'Ebono"]$q$::jsonb, $q$["Ngosso Din", "Edande Mbita", "Madola", "Mebenga m'Ebono"]$q$::jsonb, 3, $q$Né Mebenga m'Ebono dans un village bulu près d'Ebolowa, il reçoit le nom de Martin-Paul Samba à son baptême en Allemagne.$q$, $q$Born Mebenga m'Ebono in a Bulu village near Ebolowa, he was given the name Martin-Paul Samba at his baptism in Germany.$q$),
  ('heros', 'martin-paul-samba', 2, $q$Avant de devenir résistant, au service de qui Samba a-t-il été officier ?$q$, $q$Before becoming a resistance fighter, whom did Samba serve as an officer?$q$, $q$["L'administration coloniale allemande", "L'armée française de Brazzaville", "Les Britanniques du Nigeria", "Le roi Manga Bell à Douala"]$q$::jsonb, $q$["The German colonial administration", "The French army in Brazzaville", "The British in Nigeria", "King Manga Bell in Douala"]$q$::jsonb, 0, $q$Formé en Allemagne, il sert huit ans l'administration coloniale allemande. Le chemin d'un héros n'est pas toujours droit dès le premier jour.$q$, $q$Trained in Germany, he served the German colonial administration for eight years. A hero's path is not always straight from the first day.$q$),
  ('heros', 'martin-paul-samba', 3, $q$Avec quel roi duala Samba prépare-t-il en secret un soulèvement ?$q$, $q$With which Duala king did Samba secretly prepare an uprising?$q$, $q$["Charles Atangana", "Rudolf Duala Manga Bell", "Hans Dominik", "Kurt von Morgan"]$q$::jsonb, $q$["Charles Atangana", "Rudolf Duala Manga Bell", "Hans Dominik", "Kurt von Morgan"]$q$::jsonb, 1, $q$Samba s'allie à Rudolf Duala Manga Bell : l'un cherche des armes chez les Français, l'autre un appui chez les Britanniques.$q$, $q$Samba allied with Rudolf Duala Manga Bell: one sought weapons from the French, the other support from the British.$q$),
  ('heros', 'martin-paul-samba', 4, $q$Comment les Allemands découvrent-ils le projet de soulèvement de Samba en 1914 ?$q$, $q$How did the Germans discover Samba's planned uprising in 1914?$q$, $q$["Manga Bell le dénonce", "Un chef bulu le trahit", "Sa lettre aux forces françaises est interceptée", "Ses armes sont saisies à Kribi"]$q$::jsonb, $q$["Manga Bell denounces him", "A Bulu chief betrays him", "His letter to the French forces is intercepted", "His weapons are seized in Kribi"]$q$::jsonb, 2, $q$Sa lettre aux forces françaises de Brazzaville tombe entre des mains allemandes. Il est arrêté le 1er août 1914 pour haute trahison.$q$, $q$His letter to the French forces in Brazzaville fell into German hands. He was arrested on 1 August 1914 for high treason.$q$),
  ('heros', 'martin-paul-samba', 5, $q$Selon la légende populaire d'Ebolowa, qu'aurait fait Samba face au peloton ?$q$, $q$According to popular legend in Ebolowa, what did Samba do facing the firing squad?$q$, $q$["Il aurait chanté un chant de guerre bulu", "Il aurait refusé le bandeau et agité un mouchoir blanc", "Il aurait demandé pardon à l'empereur", "Il aurait remis une lettre à sa famille"]$q$::jsonb, $q$["He sang a Bulu war song", "He refused the blindfold and waved a white handkerchief", "He asked the emperor for forgiveness", "He handed a letter to his family"]$q$::jsonb, 1, $q$La tradition dit qu'il refusa le bandeau et agita un mouchoir blanc. C'est une belle légende transmise oralement : aucune archive ne la garantit.$q$, $q$Tradition says he refused the blindfold and waved a white handkerchief. It is a fine legend passed down orally: no archive confirms it.$q$),
  ('heros', 'sultan-njoya', 1, $q$Chez les Bamoun, que fallait-il rapporter au royaume pour qu'un nouveau roi règne pleinement ?$q$, $q$Among the Bamum, what had to be brought back to the kingdom for a new king to reign fully?$q$, $q$["Le trône de son père", "Le crâne de son père tombé au combat", "La lance royale de son père", "Le tambour royal du palais"]$q$::jsonb, $q$["His father's throne", "The skull of his father, fallen in battle", "His father's royal spear", "The palace's royal drum"]$q$::jsonb, 1, $q$Le roi Nsangu étant mort au combat contre les Nso, son crâne devait revenir au royaume : une question d'honneur et de légitimité pour Njoya.$q$, $q$King Nsangu had died fighting the Nso, so his skull had to return to the kingdom: a matter of honour and legitimacy for Njoya.$q$),
  ('heros', 'sultan-njoya', 2, $q$Quel cadeau Njoya offre-t-il à l'empereur Guillaume II d'Allemagne en 1908 ?$q$, $q$What gift did Njoya give to Emperor Wilhelm II of Germany in 1908?$q$, $q$["Un uniforme royal bamoun", "Un livre dans sa nouvelle écriture", "Une défense d'éléphant sculptée", "Son trône royal, le Mandu Yenu"]$q$::jsonb, $q$["A Bamum royal uniform", "A book in his new script", "A carved elephant tusk", "His royal throne, the Mandu Yenu"]$q$::jsonb, 3, $q$Il offre son trône, le Mandu Yenu, orné de perles et de cauris. Ce trône est toujours dans un musée de Berlin, au cœur du débat sur les restitutions.$q$, $q$He gave his throne, the Mandu Yenu, adorned with beads and cowries. It is still in a Berlin museum, at the heart of the restitution debate.$q$),
  ('heros', 'sultan-njoya', 3, $q$Quelle grande invention Njoya a-t-il offerte à son peuple ?$q$, $q$What great invention did Njoya give his people?$q$, $q$["Une écriture bien à lui", "Une nouvelle monnaie", "Une langue de cour secrète", "Un instrument de musique sacré"]$q$::jsonb, $q$["A script of his own", "A new currency", "A secret court language", "A sacred musical instrument"]$q$::jsonb, 0, $q$Après plus de vingt ans de travail, de 1896 à 1918, Njoya crée un syllabaire d'environ quatre-vingts signes, baptisé A ka u ku.$q$, $q$After more than twenty years of work, from 1896 to 1918, Njoya created a syllabary of about eighty signs, named A ka u ku.$q$),
  ('heros', 'sultan-njoya', 4, $q$Pourquoi la presse à imprimer de Njoya n'a-t-elle jamais servi ?$q$, $q$Why was Njoya's printing press never used?$q$, $q$["Elle a brûlé dans l'incendie du palais", "Les Allemands l'ont confisquée", "La pression de l'administration française le pousse à la détruire", "Il manquait d'encre et de papier"]$q$::jsonb, $q$["It burned in the palace fire", "The Germans confiscated it", "Pressure from the French administration drove him to destroy it", "There was no ink or paper"]$q$::jsonb, 2, $q$Prête en 1920 après sept ans de travail, la presse est détruite avant sa première impression, sous la pression de l'administration coloniale française.$q$, $q$Ready in 1920 after seven years of work, the press was destroyed before its first print run, under pressure from the French colonial administration.$q$),
  ('heros', 'sultan-njoya', 5, $q$Qui rouvre en 1985 une école pour transmettre l'écriture de Njoya ?$q$, $q$Who reopened a school in 1985 to pass on Njoya's script?$q$, $q$["Le pasteur Henri Martin", "La reine Njapdunke", "Le sultan Oumarou de Banyo", "Son fils Seidou Njimoluh Njoya"]$q$::jsonb, $q$["Pastor Henri Martin", "Queen Njapdunke", "Sultan Oumarou of Banyo", "His son Seidou Njimoluh Njoya"]$q$::jsonb, 3, $q$Presque oubliée après la mort de Njoya, son écriture renaît en 1985 grâce à son fils et successeur, Seidou Njimoluh Njoya.$q$, $q$Almost forgotten after Njoya's death, his script was revived in 1985 by his son and successor, Seidou Njimoluh Njoya.$q$),
  ('heros', 'ruben-um-nyobe', 1, $q$Que signifie Mpodol, le surnom donné à Ruben Um Nyobè ?$q$, $q$What does Mpodol, the nickname given to Ruben Um Nyobè, mean?$q$, $q$["Le lion de la forêt", "Le chef des combattants", "Celui qui porte la parole des siens", "Le gardien du village"]$q$::jsonb, $q$["The lion of the forest", "The leader of the fighters", "The one who carries the voice of his own", "The guardian of the village"]$q$::jsonb, 2, $q$Mpodol, c'est celui qui porte la parole des siens. Orateur redouté, il savait galvaniser les paysans bassa comme les diplomates de l'ONU.$q$, $q$Mpodol is the one who carries the voice of his own. A formidable speaker, he could rouse Bassa farmers and UN diplomats alike.$q$),
  ('heros', 'ruben-um-nyobe', 2, $q$Dans quel emploi le jeune Um Nyobè découvre-t-il de près l'injustice coloniale ?$q$, $q$In which job did the young Um Nyobè witness colonial injustice up close?$q$, $q$["Employé aux greffes des tribunaux", "Instituteur à la mission presbytérienne", "Infirmier à l'hôpital d'Édéa", "Commis dans une plantation"]$q$::jsonb, $q$["Clerk in the court registries", "Teacher at the Presbyterian mission", "Nurse at the Édéa hospital", "Clerk on a plantation"]$q$::jsonb, 0, $q$Employé aux greffes des tribunaux, il voit défiler chaque jour les peines et les injustices d'un droit qui n'est pas taillé pour les Camerounais.$q$, $q$As a court clerk, he saw every day the sentences and injustices of a law that was not made for Cameroonians.$q$),
  ('heros', 'ruben-um-nyobe', 3, $q$Devant quelle institution Um Nyobè plaide-t-il pour l'indépendance du Cameroun en 1952 ?$q$, $q$Before which institution did Um Nyobè argue for Cameroon's independence in 1952?$q$, $q$["L'Assemblée nationale française", "Les Nations unies, à New York", "Le congrès du RDA à Bamako", "Le Parlement britannique, à Londres"]$q$::jsonb, $q$["The French National Assembly", "The United Nations, in New York", "The RDA congress in Bamako", "The British Parliament, in London"]$q$::jsonb, 1, $q$Le 17 décembre 1952, à l'ONU, il réclame la réunification des deux Kamerun et un calendrier clair vers l'indépendance.$q$, $q$On 17 December 1952, at the UN, he called for the reunification of the two Kameruns and a clear timetable towards independence.$q$),
  ('heros', 'ruben-um-nyobe', 4, $q$Après la dissolution de l'UPC en 1955, quel chemin choisit Um Nyobè ?$q$, $q$After the UPC was dissolved in 1955, which path did Um Nyobè choose?$q$, $q$["L'exil au Caire", "L'exil au Cameroun britannique", "La reddition aux autorités françaises", "Le maquis, dans sa terre bassa"]$q$::jsonb, $q$["Exile in Cairo", "Exile in British Cameroons", "Surrender to the French authorities", "The maquis, in his Bassa homeland"]$q$::jsonb, 3, $q$Contrairement aux autres dirigeants partis en exil, il entre dans le maquis bassa et y crée même une administration parallèle.$q$, $q$Unlike the other leaders who went into exile, he entered the Bassa maquis and even set up a parallel administration there.$q$),
  ('heros', 'ruben-um-nyobe', 5, $q$En quelle année la France reconnaît-elle officiellement sa responsabilité dans la mort d'Um Nyobè ?$q$, $q$In which year did France officially acknowledge its responsibility for Um Nyobè's death?$q$, $q$["1960", "1991", "2025", "2009"]$q$::jsonb, $q$["1960", "1991", "2025", "2009"]$q$::jsonb, 2, $q$En 2025, dans une lettre à Paul Biya, Emmanuel Macron reconnaît cette responsabilité. En 1991, c'est le Cameroun qui l'avait proclamé héros national.$q$, $q$In 2025, in a letter to Paul Biya, Emmanuel Macron acknowledged this responsibility. In 1991, Cameroon had proclaimed him a national hero.$q$),
  ('heros', 'charles-atangana', 1, $q$À son baptême à la mission de Kribi, quelle « première » Atangana devient-il ?$q$, $q$At his baptism at the Kribi mission, what 'first' did Atangana become?$q$, $q$["Le premier chef ewondo nommé par les Allemands", "Le premier Ewondo diplômé en Allemagne", "Le premier Ewondo converti au catholicisme", "Le premier prêtre camerounais"]$q$::jsonb, $q$["The first Ewondo chief appointed by the Germans", "The first Ewondo to graduate in Germany", "The first Ewondo convert to Catholicism", "The first Cameroonian priest"]$q$::jsonb, 2, $q$Élève des pères pallottins à Kribi, Ntsama devient le premier Ewondo converti au catholicisme et reçoit le nom de Charles.$q$, $q$A pupil of the Pallottine fathers in Kribi, Ntsama became the first Ewondo convert to Catholicism and received the name Charles.$q$),
  ('heros', 'charles-atangana', 2, $q$Selon le récit, comment Atangana devient-il puissant ?$q$, $q$According to the story, how did Atangana become powerful?$q$, $q$["Par la force des armes", "En se rendant indispensable à l'administration coloniale", "Grâce à un héritage royal ewondo", "En menant une révolte contre les Allemands"]$q$::jsonb, $q$["By force of arms", "By making himself indispensable to the colonial administration", "Through a royal Ewondo inheritance", "By leading a revolt against the Germans"]$q$::jsonb, 1, $q$Chargé du recensement et de l'impôt chez les Ewondo dès 1902, il se rend indispensable au système colonial, un système qui pressure les siens.$q$, $q$Put in charge of the census and taxes among the Ewondo from 1902, he made himself indispensable to the colonial system, a system that squeezed his own people.$q$),
  ('heros', 'charles-atangana', 3, $q$Qu'enseigne Atangana au Collège colonial de Hambourg à partir de fin 1911 ?$q$, $q$What did Atangana teach at the Colonial College in Hamburg from late 1911?$q$, $q$["Le droit colonial", "L'histoire du Kamerun", "La médecine tropicale", "La langue ewondo"]$q$::jsonb, $q$["Colonial law", "The history of Kamerun", "Tropical medicine", "The Ewondo language"]$q$::jsonb, 3, $q$Il y enseigne l'ewondo et compile des récits, contes et proverbes beti : le Jaunde-Texte, un document précieux sur la culture ewondo.$q$, $q$He taught Ewondo there and compiled Beti stories, tales and proverbs: the Jaunde-Texte, a valuable record of Ewondo culture.$q$),
  ('heros', 'charles-atangana', 4, $q$Quand les Allemands quittent Yaoundé en 1916, que fait Atangana ?$q$, $q$When the Germans left Yaoundé in 1916, what did Atangana do?$q$, $q$["Il rejoint les troupes britanniques", "Il se cache à Mvolyé", "Il fuit avec eux jusqu'en Guinée espagnole", "Il se rend aux Français à Douala"]$q$::jsonb, $q$["He joined the British troops", "He hid in Mvolyé", "He fled with them to Spanish Guinea", "He surrendered to the French in Douala"]$q$::jsonb, 2, $q$Il fuit avec les Allemands, entraînant 72 chefs et des milliers de personnes jusqu'en Guinée espagnole. Combien l'ont suivi par choix, nul ne le sait.$q$, $q$He fled with the Germans, taking 72 chiefs and thousands of people to Spanish Guinea. How many followed him by choice, no one knows.$q$),
  ('heros', 'charles-atangana', 5, $q$Sur quoi les historiens camerounais ne tranchent-ils pas d'une seule voix ?$q$, $q$On what do Cameroonian historians not speak with one voice?$q$, $q$["S'il fut un collaborateur ou un bâtisseur pragmatique", "Le lieu de sa mort", "Le nom de sa première épouse", "Le village de sa naissance"]$q$::jsonb, $q$["Whether he was a collaborator or a pragmatic builder", "The place of his death", "The name of his first wife", "The village of his birth"]$q$::jsonb, 0, $q$Pour les uns, un collaborateur ; pour d'autres, un bâtisseur pragmatique. Les deux lectures s'appuient sur les mêmes faits : routes et écoles, mais aussi injustices.$q$, $q$For some, a collaborator; for others, a pragmatic builder. Both readings rest on the same facts: roads and schools, but also injustices.$q$),
  ('heros', 'felix-moumie', 1, $q$Quel métier Félix Moumié exerçait-il à son retour au pays en 1947 ?$q$, $q$What was Félix Moumié's profession when he returned home in 1947?$q$, $q$["Instituteur", "Infirmier", "Évangéliste", "Médecin"]$q$::jsonb, $q$["Teacher", "Nurse", "Evangelist", "Physician"]$q$::jsonb, 3, $q$Formé à Dakar dans les filières réservées aux auxiliaires africains, il revient en 1947 comme médecin colonial, affecté dans le sud du pays.$q$, $q$Trained in Dakar in the tracks reserved for African auxiliaries, he returned in 1947 as a colonial physician, posted to the south of the country.$q$),
  ('heros', 'felix-moumie', 2, $q$Dans quelle ville Moumié rencontre-t-il Ruben Um Nyobè ?$q$, $q$In which town did Moumié meet Ruben Um Nyobè?$q$, $q$["Kribi", "Douala", "Dschang", "Foumban"]$q$::jsonb, $q$["Kribi", "Douala", "Dschang", "Foumban"]$q$::jsonb, 0, $q$C'est à Kribi, petite ville côtière du sud, que sa vie bascule : il y rencontre Um Nyobè, puis rejoint l'UPC, fondée à Douala en 1948.$q$, $q$It was in Kribi, a small coastal town in the south, that his life changed: he met Um Nyobè there, then joined the UPC, founded in Douala in 1948.$q$),
  ('heros', 'felix-moumie', 3, $q$En exil au Cameroun britannique, que réclame le mouvement « One Kamerun » cofondé par Moumié ?$q$, $q$In exile in British Cameroons, what did the 'One Kamerun' movement co-founded by Moumié call for?$q$, $q$["Le retour du Cameroun sous tutelle allemande", "L'indépendance du seul Cameroun britannique", "La réunification des deux Cameroun", "Le rattachement du Cameroun au Nigeria"]$q$::jsonb, $q$["The return of Cameroon to German rule", "Independence for British Cameroons alone", "The reunification of the two Cameroons", "The union of Cameroon with Nigeria"]$q$::jsonb, 2, $q$« One Kamerun » réclame la réunification des deux Cameroun séparés par les frontières coloniales. Moumié y organise aussi 21 comités clandestins.$q$, $q$'One Kamerun' called for the reunification of the two Cameroons split apart by colonial borders. Moumié also organised 21 underground committees there.$q$),
  ('heros', 'felix-moumie', 4, $q$À Accra en 1958, de quel porte-voix du FLN algérien Moumié devient-il l'ami ?$q$, $q$In Accra in 1958, which spokesman of the Algerian FLN did Moumié befriend?$q$, $q$["Kwame Nkrumah", "Frantz Fanon", "Patrice Lumumba", "Ahmed Sékou Touré"]$q$::jsonb, $q$["Kwame Nkrumah", "Frantz Fanon", "Patrice Lumumba", "Ahmed Sékou Touré"]$q$::jsonb, 1, $q$Il se lie d'amitié avec Frantz Fanon, psychiatre martiniquais. Tous deux pensent que la colonisation ne se réforme pas, qu'elle se combat.$q$, $q$He befriended Frantz Fanon, the Martinican psychiatrist. Both believed that colonisation cannot be reformed, only fought.$q$),
  ('heros', 'felix-moumie', 5, $q$Que demande Moumié aux Nations Unies en 1959, à la tête d'une délégation de l'UPC ?$q$, $q$What did Moumié ask the United Nations for in 1959, leading a UPC delegation?$q$, $q$["L'envoi de casques bleus au Cameroun", "Le report de l'indépendance à 1965", "La libération des prisonniers de l'UPC", "Des élections libres avant l'indépendance"]$q$::jsonb, $q$["UN peacekeepers sent to Cameroon", "Independence postponed until 1965", "The release of UPC prisoners", "Free elections before independence"]$q$::jsonb, 3, $q$Il veut des élections libres avant l'indépendance. Pour lui, l'indépendance préparée sous contrôle de la France et d'Ahidjo est un trompe-l'œil.$q$, $q$He wanted free elections before independence. To him, the independence prepared under the control of France and Ahidjo was an illusion.$q$),
  ('heros', 'ernest-ouandie', 1, $q$Quel métier Ernest Ouandié exerce-t-il de 1944 à 1948, avant d'entrer à l'UPC ?$q$, $q$What was Ernest Ouandié's profession from 1944 to 1948, before he joined the UPC?$q$, $q$["Médecin", "Instituteur", "Infirmier", "Commis des douanes"]$q$::jsonb, $q$["Physician", "Teacher", "Nurse", "Customs clerk"]$q$::jsonb, 1, $q$Diplômé de l'École primaire supérieure de Yaoundé, il enseigne à Edéa, Dschang et Douala. L'école du colonisateur forme celui qui le combattra.$q$, $q$A graduate of the École primaire supérieure in Yaoundé, he taught in Edéa, Dschang and Douala. The coloniser's school trained the man who would fight it.$q$),
  ('heros', 'ernest-ouandie', 2, $q$Réfugié au Cameroun britannique, où Ouandié est-il déporté en juillet 1957 ?$q$, $q$A refugee in British Cameroons, where was Ouandié deported to in July 1957?$q$, $q$["Au Caire, en Égypte", "À Accra, au Ghana", "À Conakry, en Guinée", "À Khartoum, au Soudan"]$q$::jsonb, $q$["Cairo, in Egypt", "Accra, in Ghana", "Conakry, in Guinea", "Khartoum, in Sudan"]$q$::jsonb, 3, $q$Sous la pression française, les Britanniques le déportent à Khartoum. Il passe ensuite par Le Caire, Conakry et Accra, et devient un homme du panafricanisme.$q$, $q$Under French pressure, the British deported him to Khartoum. He then moved on to Cairo, Conakry and Accra, and became a man of the Pan-African movement.$q$),
  ('heros', 'ernest-ouandie', 3, $q$Devenu président de l'UPC, que fait Ouandié en juillet 1961 ?$q$, $q$Having become president of the UPC, what did Ouandié do in July 1961?$q$, $q$["Il rentre clandestinement au Cameroun pour diriger le combat", "Il s'installe à Accra pour diriger le parti depuis l'exil", "Il se rend à Yaoundé pour négocier avec Ahidjo", "Il part à New York plaider la cause de l'UPC à l'ONU"]$q$::jsonb, $q$["He secretly returned to Cameroon to lead the struggle", "He settled in Accra to lead the party from exile", "He went to Yaoundé to negotiate with Ahidjo", "He went to New York to plead the UPC's cause at the UN"]$q$::jsonb, 0, $q$Il rentre clandestinement pour prendre la tête du combat armé et réorganiser l'armée de libération nationale du Kamerun, dans les montagnes bamiléké et le Moungo.$q$, $q$He secretly returned to take command of the armed struggle and reorganise the national liberation army of Kamerun, in the Bamiléké mountains and the Moungo.$q$),
  ('heros', 'ernest-ouandie', 4, $q$Entre 1965 et 1970, qui tente une médiation entre Ouandié et le président Ahidjo ?$q$, $q$Between 1965 and 1970, who attempted to mediate between Ouandié and President Ahidjo?$q$, $q$["L'avocat français Jacques Vergès", "Abel Kingué, son compagnon de l'UPC", "Mgr Albert Ndongmo, évêque bamiléké", "Le président ghanéen Kwame Nkrumah"]$q$::jsonb, $q$["The French lawyer Jacques Vergès", "Abel Kingué, his UPC companion", "Bishop Albert Ndongmo, a Bamiléké bishop", "Ghanaian President Kwame Nkrumah"]$q$::jsonb, 2, $q$Mgr Ndongmo, évêque bamiléké comme lui, tente une médiation, semble-t-il à la demande du pouvoir. Il sera ensuite jugé aux côtés d'Ouandié.$q$, $q$Bishop Ndongmo, a Bamiléké like him, attempted a mediation, it seems at the request of the government. He was later tried alongside Ouandié.$q$),
  ('heros', 'ernest-ouandie', 5, $q$Avant sa reconnaissance comme héros national en 1991, comment le récit officiel présentait-il Ouandié ?$q$, $q$Before his recognition as a national hero in 1991, how did the official narrative present Ouandié?$q$, $q$["Comme un héros de l'indépendance", "Comme un rebelle, un hors-la-loi", "Comme un ancien ministre d'Ahidjo", "Comme un martyr de l'Église"]$q$::jsonb, $q$["As a hero of independence", "As a rebel, an outlaw", "As a former minister under Ahidjo", "As a martyr of the Church"]$q$::jsonb, 1, $q$Pendant vingt ans, il reste un rebelle dans le récit officiel. L'Assemblée nationale le reconnaît héros national en 1991 : la mémoire d'un pays se construit et se répare.$q$, $q$For twenty years he remained a rebel in the official narrative. The National Assembly recognised him as a national hero in 1991: a country's memory is built and repaired.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 1, $q$Dans la croyance sawa, où vivent les miengu ?$q$, $q$In Sawa belief, where do the miengu live?$q$, $q$["Au sommet du mont Cameroun", "Dans les grands arbres de la forêt", "Dans un royaume sous les eaux", "Dans les grottes du littoral"]$q$::jsonb, $q$["On the summit of Mount Cameroon", "In the tall trees of the forest", "In a kingdom beneath the waters", "In the caves along the coast"]$q$::jsonb, 2, $q$Selon les Sawa, les miengu vivent dans un royaume sous les eaux du Wouri et de l'océan, riche et ordonné, à l'image du monde des vivants mais inversé.$q$, $q$According to the Sawa, the miengu live in a kingdom beneath the waters of the Wouri and the ocean, rich and orderly, like the world of the living but reversed.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 2, $q$Selon les anciens, quel trait des miengu les Sawa voient-ils comme un signe de beauté ?$q$, $q$According to the elders, which feature of the miengu do the Sawa see as a sign of beauty?$q$, $q$["Un écart entre les dents", "Des cheveux tressés de coquillages", "Des yeux couleur d'océan", "Des scarifications sur les joues"]$q$::jsonb, $q$["A gap between the teeth", "Hair braided with shells", "Ocean-coloured eyes", "Scarification on the cheeks"]$q$::jsonb, 0, $q$Les vieux décrivent des êtres mi-humains mi-sirènes, à la bouche marquée d'un bel écart entre les dents, un signe de beauté pour les Sawa.$q$, $q$The elders describe beings half human, half mermaid, their mouths marked by a fine gap between the teeth, a sign of beauty for the Sawa.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 3, $q$D'après la tradition, lequel de ces bienfaits les miengu accordent-ils ?$q$, $q$According to tradition, which of these blessings do the miengu grant?$q$, $q$["La découverte d'or dans les rivières", "La victoire dans les guerres entre villages", "La pluie pendant la saison sèche", "La victoire dans les courses de pirogues"]$q$::jsonb, $q$["Finding gold in the rivers", "Victory in wars between villages", "Rain during the dry season", "Victory in canoe races"]$q$::jsonb, 3, $q$Les miengu apportent quatre bienfaits : poissons et crevettes, victoire aux courses de pirogues, protection contre la maladie et fin des pluies trop longues.$q$, $q$The miengu bring four blessings: fish and shrimp, victory in canoe races, protection from sickness and an end to overly long rains.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 4, $q$Comment s'appelle le maître de cérémonie de la société secrète liée aux miengu ?$q$, $q$What is the master of ceremonies of the secret society linked to the miengu called?$q$, $q$["Le jengu", "L'ekale", "Le ngondo", "Le liengu"]$q$::jsonb, $q$["The jengu", "The ekale", "The ngondo", "The liengu"]$q$::jsonb, 1, $q$La jeune fille choisie par un jengu devient guérisseuse, initiée dans une société secrète dirigée par l'ekale, qui portait autrefois un masque.$q$, $q$The girl chosen by a jengu becomes a healer, initiated into a secret society led by the ekale, who once wore a mask.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 5, $q$Lors du Ngondo, que dit-on du plongeur qui ressort des eaux du Wouri ?$q$, $q$At the Ngondo, what is said of the diver who comes back up from the Wouri?$q$, $q$["Qu'il a vaincu un jengu sous l'eau", "Qu'il rapporte de l'or du fond du fleuve", "Qu'il revient du royaume des miengu avec une prophétie", "Qu'il devient le nouveau chef des Sawa"]$q$::jsonb, $q$["That he has defeated a jengu underwater", "That he brings gold up from the riverbed", "That he returns from the miengu kingdom with a prophecy", "That he becomes the new chief of the Sawa"]$q$::jsonb, 2, $q$Il reste sous l'eau, selon les témoins, de 3 à 10 minutes. On dit qu'il revient porteur d'une prophétie : une croyance qu'on ne peut ni prouver ni réfuter.$q$, $q$Witnesses say he stays underwater for 3 to 10 minutes. He is said to return with a prophecy: a belief that can be neither proven nor disproven.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 1, $q$Selon la tradition, pourquoi le peuple préfère-t-il Nchare à son frère Koumjouom ?$q$, $q$According to tradition, why do the people prefer Nchare to his brother Koumjouom?$q$, $q$["Parce qu'il est le plus grand et le plus fort", "Parce qu'il est l'aîné des trois enfants", "Parce qu'il écoute et partage au lieu de mépriser", "Parce qu'il a déjà gagné une guerre"]$q$::jsonb, $q$["Because he is the tallest and strongest", "Because he is the eldest of the three children", "Because he listens and shares instead of scorning", "Because he has already won a war"]$q$::jsonb, 2, $q$Koumjouom est grand, fort et arrogant ; Nchare, petit et frêle, écoute et partage. La modestie pèse parfois plus lourd que la stature.$q$, $q$Koumjouom is tall, strong and arrogant; Nchare, small and frail, listens and shares. Modesty sometimes weighs more than stature.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 2, $q$Dans la tradition bamoun, quelle épreuve décide qui deviendra roi ?$q$, $q$In Bamum tradition, which trial decides who will become king?$q$, $q$["Une course jusqu'à une pierre", "Un combat à la lance", "Une grande partie de chasse", "Un concours de danse"]$q$::jsonb, $q$["A race to a stone", "A spear fight", "A great hunt", "A dance contest"]$q$::jsonb, 0, $q$Les trois prétendants partent assis sur un même tronc d'arbre. Le premier qui pose le pied sur une pierre, à une centaine de mètres, devient roi.$q$, $q$The three contenders start seated on the same tree trunk. The first to set foot on a stone about a hundred metres away becomes king.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 3, $q$Dans le récit, comment Mfom empêche-t-elle Koumjouom de gagner la course ?$q$, $q$In the story, how does Mfom stop Koumjouom from winning the race?$q$, $q$["Elle lui fait boire du vin de palme", "Elle cache la pierre d'arrivée", "Elle le fait trébucher au départ", "Elle s'assoit sur un pan de son pagne"]$q$::jsonb, $q$["She makes him drink palm wine", "She hides the finishing stone", "She trips him at the start", "She sits on a fold of his loincloth"]$q$::jsonb, 3, $q$Sur le conseil de Njimongha, Mfom coince sous elle le pagne de son frère. Retenu quelques secondes, Koumjouom laisse Nchare atteindre la pierre.$q$, $q$Advised by Njimongha, Mfom traps her brother's loincloth under her. Held back for a few seconds, Koumjouom lets Nchare reach the stone.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 4, $q$Selon le récit, quel descendant de la lignée de Nchare Yen inventa une écriture pour son peuple ?$q$, $q$According to the story, which descendant of Nchare Yen's line invented a script for his people?$q$, $q$["Charles Atangana", "Le roi Njoya", "Rudolf Douala Manga Bell", "Martin Paul Samba"]$q$::jsonb, $q$["Charles Atangana", "King Njoya", "Rudolf Douala Manga Bell", "Martin Paul Samba"]$q$::jsonb, 1, $q$Nchare Yen est, selon la tradition, le premier des mfon bamoun. Bien plus tard, son descendant le roi Njoya inventera une écriture propre à son peuple.$q$, $q$According to tradition, Nchare Yen was the first of the Bamum mfon. Much later, his descendant King Njoya would invent a script of his people's own.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 5, $q$D'où vient presque tout ce que l'on sait de Nchare Yen ?$q$, $q$Where does almost everything we know about Nchare Yen come from?$q$, $q$["Des écrits laissés par des témoins de 1394", "Des archives des missionnaires allemands", "De la tradition orale bamoun", "Des fouilles archéologiques à Foumban"]$q$::jsonb, $q$["Writings left by witnesses in 1394", "The archives of German missionaries", "Bamum oral tradition", "Archaeological digs in Foumban"]$q$::jsonb, 2, $q$Son histoire vient de la tradition orale, consignée bien plus tard. Aucun témoin de 1394 n'a laissé d'écrit : c'est un récit fondateur, pas un procès-verbal.$q$, $q$His story comes from oral tradition, written down much later. No witness from 1394 left any writing: it is a founding story, not an official record.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 1, $q$Selon la tradition, de quel ancêtre commun descendent tous les Beti ?$q$, $q$According to tradition, which common ancestor are all the Beti descended from?$q$, $q$["Ngan Medza", "Nanga", "Nchare Yen", "Mvondo"]$q$::jsonb, $q$["Ngan Medza", "Nanga", "Nchare Yen", "Mvondo"]$q$::jsonb, 1, $q$La tradition fait descendre les Beti de Nanga, décrit comme albinos, et de ses sept enfants, d'où viennent Eton, Ewondo, Bulu, Bene, Ntumu, Fang…$q$, $q$Tradition has the Beti descend from Nanga, described as albino, and his seven children, from whom come the Eton, Ewondo, Bulu, Bene, Ntumu, Fang…$q$),
  ('mythe', 'mythe-ngan-medza-beti', 2, $q$Sur quel point le griot invite-t-il à la prudence à propos de la fuite des Beti ?$q$, $q$On what point does the griot urge caution about the flight of the Beti?$q$, $q$["Leur origine du côté de l'Adamaoua", "Le nombre des enfants de Nanga", "Le lien avec le nom d'Ousman dan Fodio", "Le nom exact du serpent"]$q$::jsonb, $q$["Their origin towards the Adamawa", "The number of Nanga's children", "The link with the name of Usman dan Fodio", "The exact name of the serpent"]$q$::jsonb, 2, $q$Beaucoup de traditions relient cette fuite à dan Fodio, mais son jihad commence vers 1800 alors que la migration s'étale sur plusieurs générations.$q$, $q$Many traditions link this flight to dan Fodio, but his jihad began around 1800, whereas the migration stretched over several generations.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 3, $q$Dans le mythe, comment Ngan Medza aide-t-il les Beti à franchir la Sanaga ?$q$, $q$In the myth, how does Ngan Medza help the Beti cross the Sanaga?$q$, $q$["Il s'allonge d'une rive à l'autre comme un pont vivant", "Il assèche le fleuve d'un coup de queue", "Il leur montre un gué caché", "Il chasse les poursuivants venus du nord"]$q$::jsonb, $q$["It stretches from bank to bank like a living bridge", "It dries up the river with a flick of its tail", "It shows them a hidden ford", "It drives off the pursuers from the north"]$q$::jsonb, 0, $q$Selon les anciens, Dieu envoie le serpent géant Ngan Medza, qui s'allonge d'une rive à l'autre et offre son dos comme pont au peuple en fuite.$q$, $q$According to the elders, God sends the giant serpent Ngan Medza, which stretches from bank to bank and offers its back as a bridge to the fleeing people.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 4, $q$Que disent les deux versions du mythe sur ce qui blesse le serpent ?$q$, $q$What do the two versions of the myth say wounded the serpent?$q$, $q$["Une pierre ou une flèche", "Un crocodile ou un orage", "La foudre ou un autre serpent", "Une lance ou la flamme d'une torche"]$q$::jsonb, $q$["A stone or an arrow", "A crocodile or a storm", "Lightning or another serpent", "A spear or the flame of a torch"]$q$::jsonb, 3, $q$Pour les uns, un guerrier plante sa lance dans son dos ; pour d'autres, la flamme de la torche tombe sur son échine. Le peuple reste dispersé des deux côtés.$q$, $q$Some say a warrior drove his spear into its back; others that the torch flame fell on its spine. The people stayed scattered on both banks.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 5, $q$Selon la tradition, que fit Ngan Medza avant de disparaître dans les eaux ?$q$, $q$According to tradition, what did Ngan Medza do before disappearing into the water?$q$, $q$["Il maudit le guerrier qui l'avait blessé", "Il donna des conseils pour vivre en harmonie avec la nature", "Il promit de revenir porter les Beti", "Il désigna le premier chef des Beti"]$q$::jsonb, $q$["It cursed the warrior who had wounded it", "It gave advice on living in harmony with nature", "It promised to return to carry the Beti", "It named the first chief of the Beti"]$q$::jsonb, 1, $q$On raconte qu'il conseilla les siens et les avertit des dangers à venir. Sculptures, chants et fêtes gardent aujourd'hui encore sa mémoire.$q$, $q$It is said it advised its people and warned them of dangers to come. Carvings, songs and festivals still keep his memory alive today.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 1, $q$Que signifie « Ngog Lituba » dans la langue des Bassa ?$q$, $q$What does 'Ngog Lituba' mean in the Bassa language?$q$, $q$["Le rocher percé", "La montagne sacrée", "La porte du fleuve", "La maison des ancêtres"]$q$::jsonb, $q$["The pierced rock", "The sacred mountain", "The gate of the river", "The house of the ancestors"]$q$::jsonb, 0, $q$Ngog Lituba signifie « le rocher percé » : une roche de 1 500 m près d'Édéa, avec à son flanc une grotte d'où, selon les Bassa, leurs ancêtres sont sortis.$q$, $q$Ngog Lituba means 'the pierced rock': a 1,500 m rock near Édéa with a cave on its side, from which, the Bassa say, their ancestors came out.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 2, $q$Dans la tradition, qu'est-ce qui sauve les deux ancêtres cachés dans la grotte ?$q$, $q$In the tradition, what saves the two ancestors hidden in the cave?$q$, $q$["Un éboulement qui ferme l'entrée", "Un serpent géant qui garde la grotte", "Une toile d'araignée tissée à l'entrée", "Un épais brouillard sur la forêt"]$q$::jsonb, $q$["A rockfall that blocks the entrance", "A giant serpent guarding the cave", "A spider's web woven across the entrance", "A thick fog over the forest"]$q$::jsonb, 2, $q$En une nuit, une araignée tisse sa toile à l'entrée. Voyant la toile intacte, les poursuivants croient la grotte vide et repartent.$q$, $q$In a single night, a spider weaves its web across the entrance. Seeing the web intact, the pursuers think the cave is empty and leave.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 3, $q$Selon le récit, quels peuples sont issus des enfants du rocher percé ?$q$, $q$According to the story, which peoples descend from the children of the pierced rock?$q$, $q$["Les Bassa, les Duala et les Bakweri", "Les Ewondo, les Eton et les Bulu", "Les Bamoun, les Tikar et les Bamiléké", "Les Bassa, les Bakoko et les Bati"]$q$::jsonb, $q$["The Bassa, the Duala and the Bakweri", "The Ewondo, the Eton and the Bulu", "The Bamum, the Tikar and the Bamiléké", "The Bassa, the Bakoko and the Bati"]$q$::jsonb, 3, $q$Par vagues successives, les clans quittent Ngog Lituba et donnent naissance aux Bassa, aux Bakoko (ou Elog Mpo'o) et aux Bati, qui se disent cousins.$q$, $q$In successive waves, the clans leave Ngog Lituba and give rise to the Bassa, the Bakoko (or Elog Mpo'o) and the Bati, who call one another cousins.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 4, $q$Quelle hypothèse certains géologues avancent-ils à propos du rocher ?$q$, $q$What hypothesis do some geologists put forward about the rock?$q$, $q$["Une ancienne île de l'océan", "Un ancien cratère, volcanique ou météoritique", "Un rocher taillé par la main de l'homme", "Une ancienne mine de fer"]$q$::jsonb, $q$["A former island in the ocean", "An ancient crater, volcanic or meteoritic", "A rock carved by human hands", "A former iron mine"]$q$::jsonb, 1, $q$La science ne confirme ni ne contredit le mythe : la roche porte des traces volcaniques, et certains y voient un ancien cratère érodé par les millénaires.$q$, $q$Science neither confirms nor contradicts the myth: the rock bears volcanic marks, and some see in it an ancient crater worn down over millennia.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 5, $q$Pourquoi des communautés sont-elles allées jusqu'aux Nations Unies en 2006 ?$q$, $q$Why did communities take their case all the way to the United Nations in 2006?$q$, $q$["Pour obtenir des fouilles archéologiques", "Pour classer la forêt en parc national", "Pour faire reconnaître le caractère sacré du site", "Pour interdire le site aux touristes"]$q$::jsonb, $q$["To obtain archaeological digs", "To have the forest made a national park", "To have the sacred character of the site recognised", "To close the site to tourists"]$q$::jsonb, 2, $q$Après l'installation en 1959 d'une croix et d'une statue de la Vierge au sommet, elles se sont senties dépossédées et ont défendu leur lieu sacré.$q$, $q$After a cross and a statue of the Virgin were erected on the summit in 1959, they felt dispossessed and stood up for their sacred place.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 1, $q$Selon les récits kotoko, qu'étaient les Sao ?$q$, $q$According to Kotoko stories, what were the Sao?$q$, $q$["Des esprits de l'eau", "Des chasseurs nomades", "Des magiciens du désert", "Des géants"]$q$::jsonb, $q$["Water spirits", "Nomadic hunters", "Desert sorcerers", "Giants"]$q$::jsonb, 3, $q$Pour les Kotoko, leurs ancêtres sao étaient des géants d'une force surhumaine, qui marchaient avec des troncs de rôniers en guise de cannes.$q$, $q$For the Kotoko, their Sao ancestors were giants of superhuman strength, who walked with whole borassus palm trunks as canes.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 2, $q$D'après la légende, que se passait-il quand un chef sao de Goulfey éternuait ?$q$, $q$According to the legend, what happened when a Sao chief from Goulfey sneezed?$q$, $q$["Les oiseaux s'envolaient à une lieue à la ronde", "La terre tremblait sous le village", "Le lac Tchad sortait de son lit", "Le vent couchait les arbres"]$q$::jsonb, $q$["The birds took flight for a league around", "The ground shook beneath the village", "Lake Chad burst its banks", "The wind flattened the trees"]$q$::jsonb, 0, $q$Selon la légende, il lui suffisait d'éternuer pour faire fuir les oiseaux à une lieue à la ronde : la mesure que la tradition donne à ce peuple.$q$, $q$According to the legend, he only had to sneeze to send the birds flying for a league around: the measure tradition gives this people.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 3, $q$Qui a fouillé les rives du lac Tchad et du Logone sur les traces des Sao ?$q$, $q$Who excavated the shores of Lake Chad and the Logone in search of the Sao?$q$, $q$["Un missionnaire allemand de Garoua", "L'explorateur Heinrich Barth", "L'archéologue Jean-Paul Lebeuf et son épouse", "Une équipe de l'université de Yaoundé"]$q$::jsonb, $q$["A German missionary from Garoua", "The explorer Heinrich Barth", "The archaeologist Jean-Paul Lebeuf and his wife", "A team from the University of Yaoundé"]$q$::jsonb, 2, $q$L'archéologue Jean-Paul Lebeuf et son épouse y ont fouillé pendant des décennies, à partir du milieu du XXe siècle. Ce qu'ils ont trouvé n'était plus un mythe.$q$, $q$The archaeologist Jean-Paul Lebeuf and his wife excavated there for decades from the mid-20th century. What they found was no longer a myth.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 4, $q$Qu'a révélé l'archéologie, à la place des géants de la légende ?$q$, $q$What did archaeology reveal, instead of the giants of legend?$q$, $q$["Des squelettes de très grande taille", "Des artisans, bâtisseurs et potiers de talent", "Des pyramides comme en Égypte", "Une cité engloutie par le lac"]$q$::jsonb, $q$["Skeletons of enormous size", "Talented craftsmen, builders and potters", "Pyramids like those in Egypt", "A city swallowed by the lake"]$q$::jsonb, 1, $q$Poteries, bronzes, cités entourées de murailles de terre : l'archéologie a exhumé une civilisation réelle d'artisans et de bâtisseurs, pas des géants.$q$, $q$Pottery, bronzes, towns ringed with earthen walls: archaeology unearthed a real civilisation of craftsmen and builders, not giants.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 5, $q$Comment les Kotoko racontent-ils leur lien avec les Sao ?$q$, $q$How do the Kotoko describe their link with the Sao?$q$, $q$["Comme leurs vainqueurs", "Comme un peuple sans lien avec eux", "Comme leurs héritiers directs", "Comme des voyageurs venus du Nil"]$q$::jsonb, $q$["As their conquerors", "As a people with no link to them", "As their direct heirs", "As travellers from the Nile"]$q$::jsonb, 2, $q$Ils racontent une continuité : après de longues épreuves rituelles, le prince kotoko est reconnu comme l'héritier direct des souverains sao.$q$, $q$They tell of continuity: after long ritual ordeals, the Kotoko prince is recognised as the direct heir of the Sao sovereigns.$q$)
