-- Quiz AFROBACK : questions des contenus publiés (héros et mythes)
-- Source : export de la base du 2026-10-07 (recit_chapitres_fr / recit_chapitres_en). Rédigé par l'agent afroback-quiz.
-- BROUILLON : à relire par Yannick (FR) et par un anglophone (EN) avant exécution. Rejouable (on conflict do update).
-- bonne_reponse = index à partir de 0 dans choix_fr (même index dans choix_en).

on conflict (type_contenu, slug, ordre) do update set
  question_fr = excluded.question_fr, question_en = excluded.question_en,
  choix_fr = excluded.choix_fr, choix_en = excluded.choix_en,
  bonne_reponse = excluded.bonne_reponse,
  explication_fr = excluded.explication_fr, explication_en = excluded.explication_en,
  updated_at = now();

-- Contrôle : chaque contenu doit avoir exactement 5 questions.
select type_contenu, slug, count(*) as nb_questions
from public.quiz_questions
group by type_contenu, slug
order by type_contenu, slug;
